/* Lua 5.4 as a flat-pair workload: the same wl_* contract as the generated workload, so the
 * same driver.cpp and the same runners/bench apply. Every phase starts from a FRESH Lua state
 * on a reset heap (untimed), so lo and hi run the identical route prefix. */
#include "lua.h"
#include "lauxlib.h"
#include "lualib.h"
#include "platform.h"
#include "lua_script.h"   /* generated by build-lua.mjs from bench.lua: BS_LUA_SCRIPT */

void bs_heap_reset(void);
void bs_out(u32 v);
void abort(void);

static lua_State* L;

void bs_lua_throw(int status) {
    bs_out(0xDEAD1000u | (u32)status);
    if (L && lua_gettop(L) > 0 && lua_type(L, -1) == LUA_TSTRING) {
        const char* m = lua_tostring(L, -1);
        u32 h = 0;
        while (*m) h = h * 31u + (unsigned char)*m++;
        bs_out(h);
    }
    abort();
}

static void* l_alloc(void* ud, void* ptr, size_t osize, size_t nsize) {
    (void)ud; (void)osize;
    if (nsize == 0) { free(ptr); return NULL; }
    return realloc(ptr, nsize);
}

void wl_setup(void) {}

void wl_reset(u32 seed) {
    (void)seed;
    bs_heap_reset();
    bs_print_hash = 2166136261u;
    bs_print_bytes = 0;
    L = lua_newstate(l_alloc, NULL);
    luaL_requiref(L, LUA_GNAME, luaopen_base, 1);
    luaL_requiref(L, LUA_TABLIBNAME, luaopen_table, 1);
    luaL_requiref(L, LUA_STRLIBNAME, luaopen_string, 1);
    luaL_requiref(L, LUA_MATHLIBNAME, luaopen_math, 1);
    lua_settop(L, 0);
    if (luaL_loadbuffer(L, BS_LUA_SCRIPT, sizeof(BS_LUA_SCRIPT) - 1, "=bench") != LUA_OK) bs_lua_throw(100);
    lua_call(L, 0, 0);
}

u32 wl_run(u32 seed, u32 steps) {
    u32 r;
    lua_getglobal(L, "run");
    lua_pushinteger(L, (lua_Integer)steps);
    lua_pushinteger(L, (lua_Integer)(seed & 0x7fffffffu));
    lua_call(L, 2, 1);
    r = (u32)lua_tointeger(L, -1);
    lua_pop(L, 1);
    return r;
}

u32 wl_hash(void) {
    return bs_print_hash ^ (bs_print_bytes * 2654435761u) ^ ((u32)lua_gc(L, LUA_GCCOUNT, 0) << 20);
}
